_hx_print = print or (function() end)

_hx_table = {}
_hx_table.pack = _G.table.pack or function(...)
    return {...}
end
_hx_table.unpack = _G.table.unpack or _G.unpack
_hx_table.maxn = _G.table.maxn or function(t)
  local maxn=0;
  for i in pairs(t) do
    maxn=type(i)=='number'and i>maxn and i or maxn
  end
  return maxn
end;

function _hx_handle_error(obj)
  local message = tostring(obj)
  if _G.debug and _G.debug.traceback then
    -- level 2 to skip _hx_handle_error
    message = _G.debug.traceback(message, 2)
  end
  return setmetatable({}, { __tostring = function() return message end })
end

_hx_static_init();
local success, err = _G.xpcall(function() 
  Main.main();
  __haxe_EntryPoint.run();
  _hx_luv.run();
end, _hx_handle_error)
if not success then _G.error(err) end

end
setfenv(initialize, environment)
initialize()
environment.OimoExports.array = function(values)
 local array = {}; for i, value in ipairs(values) do array[i-1]=value end
 return environment._hx_tab_array(array, #values)
end
return environment.OimoExports
